// Apenas entrada: nenhuma mensagem e enviada ao WhatsApp.
const output = [];
for (const [index, item] of $input.all().entries()) {
  const root = item.json.body ?? item.json;
  const values = root.entry
    ? root.entry.flatMap(entry => (entry.changes ?? []).map(change => change.value))
    : [root];
  for (const value of values) {
    if (!value || value.metadata?.phone_number_id !== '1280781558460646') continue;
    for (const message of value.messages ?? []) {
      if (typeof message.id !== 'string' || !/^wamid\.[A-Za-z0-9+/=_-]{1,480}$/.test(message.id)) {
        throw new Error('Identificador WhatsApp invalido; evento nao processado.');
      }
      if (typeof message.from !== 'string' || !/^[0-9]{6,20}$/.test(message.from)) {
        throw new Error('Remetente sem numero suportado neste piloto.');
      }
      const text = message.type === 'text' ? message.text?.body
        : '[WhatsApp: mensagem de tipo ' + String(message.type ?? 'desconhecido') + '. Preciso de atendimento humano; midia nao processada neste piloto.]';
      if (typeof text !== 'string' || !text.trim() || text.length > 2000) {
        throw new Error('Texto vazio ou acima de 2000 caracteres; revisar execucao.');
      }
      output.push({
        json: {message: text, request_id: message.id, session_id: 'wa_' + message.from},
        pairedItem: {item: index}
      });
    }
  }
}
return output;
